//! Actions-only explicit current READ -> real peer snapshot -> same SQL roster.
use super::*;
fn roster_config(root:&str,port:u16)->AccountConfig{let mut c=directory_config(root,port,3000,true,false);c.profile.relation_events=Some(n::group_events::NativeRelationEventsConfig{group_updates:true});c.profile.org_relation_sync=Some(n::org_relation_sync::NativeOrgRelationSyncConfig{receive:true});c.profile.relation_roster=Some(n::relation_roster::NativeRelationRosterConfig{observe:true});c}
fn result(partial:bool,time:i64,first:&[&[u8]],second:&[&[u8]],removed:&[&[u8]])->Vec<u8>{let mut w=Writer::new();w.boolean(true).unwrap();w.boolean(partial).unwrap();for items in [first,second]{w.u32(items.len()as u32).unwrap();for label in items{w.bytes(label).unwrap();w.u32(1).unwrap();w.bytes(b"private-note").unwrap();w.bytes(b"").unwrap();w.properties(&[]).unwrap();}}w.u32(removed.len()as u32).unwrap();for label in removed{w.bytes(label).unwrap();}w.i64(time).unwrap();w.bytes(b"").unwrap();w.finish().expose_to_transport().to_vec()}
fn group_event(id:i32,base:i64,time:i64,label:&[u8])->Vec<u8>{let mut b=Writer::new();b.u32(1).unwrap();b.bytes(label).unwrap();b.u32(1).unwrap();b.bytes(b"private-note").unwrap();b.bytes(b"").unwrap();b.properties(&[]).unwrap();let base=base.to_string();let time=time.to_string();let mut a=Writer::versioned().unwrap();a.bytes(b"Group.Update").unwrap();a.properties(&[RpcProperty{key:b"Group.GroupId",value:b"1-2"},RpcProperty{key:b"Group.LastUpdateTime",value:base.as_bytes()},RpcProperty{key:b"Group.UpdateTime",value:time.as_bytes()}]).unwrap();a.bytes(b.finish().expose_to_transport()).unwrap();direct(id,n::rpc_incoming::ONLINE_MESSAGE_METHOD.as_bytes(),a.finish().expose_to_transport(),b"MessageReceiver",None)}
async fn event_reply(peer:&mut CommonPeer,last:&mut Option<i32>){loop{let bytes=peer.next().await.unwrap();if bytes[0]==1{let r=decode_reply(&bytes[1..]).unwrap();assert_eq!(r.call_id,91);assert_eq!(r.result_code,0);assert_eq!(r.result_stream,[0,1,0,0,0,0]);return;}ordinary_poll(peer,&bytes,last).await;}}
async fn ready(manager:&AccountManager,line:&str){bounded(async{while manager.get(line,100).await.unwrap().phase!="hosted"{tokio::task::yield_now().await;}}).await;}
#[tokio::test]async fn roster_account_explicit_full_then_partial_uses_original_uid_group_since_and_no_write_or_new_connection(){Box::pin(async{
 let cert=Certificates::generate("IP:127.0.0.1");let listener=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let port=listener.local_addr().unwrap().port();let server=cert.server_config(&TLS13);let temp=TempDatabase::new();let manager=AccountManager::new(temp.database.clone());let account=manager.create(roster_config(&cert.root,port),100).await.unwrap().account;let line=account.line_id.clone();let peer=tokio::spawn(Box::pin(async move{bounded(async move{let mut p=CommonPeer::open(listener,server).await;let bytes=p.next().await.unwrap();let login=decode_request(&bytes[1..]).unwrap();p.send(&[reply(login.call_id,&login_result())]).await;let(_,flag)=hosting_call(&mut p).await;assert_eq!(flag,b"4");let mut last=None;let id=directory_packet(&mut p,Some("1-2"),-1,false,&mut last).await;p.send(&[reply(id,&result(false,7,&[b"one",b"two"],&[],&[]))]).await;let id=directory_packet(&mut p,Some("1-2"),7,false,&mut last).await;p.send(&[reply(id,&result(true,9,&[b"three"],&[b"one"],&[b"two"]))]).await;finish_account(&mut p).await;}).await}));
 bounded(manager.start(&line,1,100)).await.unwrap();ready(&manager,&line).await;for(since,wanted)in[(-1,"snapshot"),(7,"incremental")]{let prepared=manager.prepare_relation_roster(&line,1,Some("1-2"),since,true).unwrap();let value=bounded(manager.finish_relation_roster(prepared)).await.unwrap();assert_eq!(value.outcome,wanted);assert!(value.complete_roster);assert_eq!(value.members,2);}let rows=manager.relation_roster_history(&line,128).unwrap();assert_eq!(rows.len(),1);assert_eq!(rows[0].observed_time.as_deref(),Some("9"));assert!(rows[0].historical_complete);assert!(manager.relation_write_history(&line,128).unwrap().is_empty());assert!(manager.im_messages(&line,16).unwrap().is_empty());assert!(!bounded(manager.stop(&line,1,100)).await.unwrap().io_cleanup_required);bounded(peer).await.unwrap();assert!(!temp.database.with_conn(|c|n::account_runs::ownership_pending(c,&line)).unwrap());bounded(manager.delete(&line,1)).await.unwrap();let count:i64=temp.database.with_conn(|c|c.query_row("SELECT COUNT(*) FROM app_voice_relation_roster_members",[],|r|r.get(0)).map_err(|_|"fixture")).unwrap();assert_eq!(count,0);
}).await;}
#[tokio::test]async fn roster_account_group_event_during_read_makes_old_snapshot_superseded_then_explicit_read_recovers(){Box::pin(async{
 let cert=Certificates::generate("IP:127.0.0.1");let listener=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let port=listener.local_addr().unwrap().port();let server=cert.server_config(&TLS13);let temp=TempDatabase::new();let manager=AccountManager::new(temp.database.clone());let account=manager.create(roster_config(&cert.root,port),100).await.unwrap().account;let line=account.line_id.clone();let peer=tokio::spawn(Box::pin(async move{bounded(async move{let mut p=CommonPeer::open(listener,server).await;let bytes=p.next().await.unwrap();let login=decode_request(&bytes[1..]).unwrap();p.send(&[reply(login.call_id,&login_result())]).await;let(_,flag)=hosting_call(&mut p).await;assert_eq!(flag,b"4");let mut last=None;let id=directory_packet(&mut p,Some("1-2"),-1,false,&mut last).await;p.send(&[group_event(91,1,2,b"newer")]).await;event_reply(&mut p,&mut last).await;p.send(&[reply(id,&result(false,1,&[b"old"],&[],&[]))]).await;let id=directory_packet(&mut p,Some("1-2"),-1,false,&mut last).await;p.send(&[reply(id,&result(false,2,&[b"newer"],&[],&[]))]).await;finish_account(&mut p).await;}).await}));
 bounded(manager.start(&line,1,100)).await.unwrap();ready(&manager,&line).await;let p=manager.prepare_relation_roster(&line,1,Some("1-2"),-1,true).unwrap();let old=bounded(manager.finish_relation_roster(p)).await.unwrap();assert_eq!(old.outcome,"superseded");assert!(!old.complete_roster);assert!(manager.relation_roster_history(&line,128).unwrap()[0].gap);let p=manager.prepare_relation_roster(&line,1,Some("1-2"),-1,true).unwrap();let actual=bounded(manager.finish_relation_roster(p)).await.unwrap();assert_eq!(actual.outcome,"snapshot");assert!(actual.complete_roster);assert_eq!(actual.members,1);assert!(!bounded(manager.stop(&line,1,100)).await.unwrap().io_cleanup_required);bounded(peer).await.unwrap();
}).await;}
#[tokio::test]async fn roster_account_missing_consent_revision_or_policy_never_admits_native_read(){Box::pin(async{
 let cert=Certificates::generate("IP:127.0.0.1");let temp=TempDatabase::new();let manager=AccountManager::new(temp.database.clone());let c=manager.create(roster_config(&cert.root,1),100).await.unwrap().account;assert_eq!(manager.prepare_relation_roster(&c.line_id,1,None,-1,false).err(),Some("app_account_directory_consent_required"));assert_eq!(manager.prepare_relation_roster(&c.line_id,2,None,-1,true).err(),Some("app_account_revision_conflict"));assert!(manager.prepare_relation_roster(&c.line_id,1,None,-1,true).is_err());assert!(manager.relation_roster_history(&c.line_id,128).unwrap().is_empty());assert_eq!(manager.get(&c.line_id,100).await.unwrap().phase,"stopped");
}).await;}
